import { icon, logo } from './icons.js';
import { appearanceControls } from './appearance.js';
export const esc = value => String(value ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const btn=(label,action,cls='',ico='',data='')=>`<button type="button" class="btn ${cls}" data-action="${action}" ${data}>${ico?icon(ico,17):''}${label}</button>`;
export function publicNav(active='home') { return `<nav class="landing-nav" aria-label="Public navigation"><a class="wordmark" href="/">${logo}loop</a><div class="public-links"><a href="/#connected">Why Loop</a><a href="/#workspace">Workspace</a><a href="/pricing" ${active==='pricing'?'aria-current="page"':''}>Pricing</a></div><div class="public-actions"><button class="appearance-trigger" data-action="appearance" aria-label="Appearance settings">${icon('sun',17)}<span>Appearance</span></button>${btn('Explore Loop','explore','quiet','arrow')}</div></nav>`; }
export function publicFooter(){return `<footer class="landing-footer"><a class="wordmark" href="/">${logo}loop</a><span>Work, in harmony.</span><a href="/pricing">Pricing</a><button data-action="appearance">Appearance</button><span>© ${new Date().getFullYear()} Loop · Independent product concept</span></footer>`;}
export function appearancePanel(){return `<div class="appearance-panel"><p>Make a little space that feels like you.</p>${appearanceControls()}<div class="appearance-sample"><div class="sample-window"><i></i><i></i><i></i><span></span><b></b></div><span>Same Loop.<br><strong>Your point of view.</strong></span></div><small>Your choices are saved in this browser. Your workspace data stays intact.</small></div>`;}
